        if (s_context == NULL) {
            errmsg.LogError(0, RS_RET_NO_ERRCODE,
                            "omzmq3: zctx_new failed: %s", zmq_strerror(errno));
            ABORT_FINALIZE(RS_RET_NO_ERRCODE);
        }
        if (s_workerThreads > 0) zctx_set_iothreads(s_context, s_workerThreads);
    }

