void ScriptLoader::executeScript(const ScriptSourceCode& sourceCode)
{
    ASSERT(m_alreadyStarted);

    if (sourceCode.isEmpty())
        return;

    RefPtr<Document> elementDocument(m_element->document());
    RefPtr<Document> contextDocument = elementDocument->contextDocument().get();
    if (!contextDocument)
        return;

    LocalFrame* frame = contextDocument->frame();

    ContentSecurityPolicy* contentSecurityPolicy = elementDocument->contentSecurityPolicy();
    if (!contentSecurityPolicy)
        return;

    bool shouldBypassMainWorldContentSecurityPolicy = (frame && frame->script().shouldBypassMainWorldContentSecurityPolicy()) || contentSecurityPolicy->allowScriptNonce(m_element->fastGetAttribute(HTMLNames::nonceAttr)) || contentSecurityPolicy->allowScriptHash(sourceCode.source());

