tsl::StatusOr<StreamExecutor*> CudaPlatform::FirstExecutorForBus(
    int bus_ordinal) {
  InspectNumaNodes();
  if (bus_ordinal < 0 || bus_ordinal >= BusCount()) {
    return tsl::Status(
        port::error::INVALID_ARGUMENT,
        absl::StrFormat("bus ordinal %d out of available range [0, %d).",
                        bus_ordinal, BusCount()));
  }
  for (int i = 0; i < VisibleDeviceCount(); i++) {
    if (DeviceToBus(i) == bus_ordinal) {
      return *ExecutorForDevice(i);
    }
  }

  return tsl::Status(
      port::error::NOT_FOUND,
      absl::StrFormat("Executor for bus %d not found.", bus_ordinal));
}

