char *url_decode_r(char *to, char *url, size_t size) {
    char *s = url,           // source
         *d = to,            // destination
         *e = &to[size - 1]; // destination end

    if(size == 0) {
        return to;
    }

    while(*s && d < e) {
        if(unlikely(*s == '%')) {
            if(likely(s[1] && s[2])) {
                int hi = from_hex(s[1]);
                int lo = from_hex(s[2]);
                if(hi >= 0 && lo >= 0) {
                    *d++ = (char)((hi << 4) | lo);
                    s += 2;
                }
            }
        }
        else if(unlikely(*s == '+'))
            *d++ = ' ';

        else
            *d++ = *s;

        s++;
    }

    *d = '\0';

    return to;
}

